-- Migration 891: plain INSERT (not INSERT SELECT FROM VALUES) for the
-- remaining 142-row gap window -- migration 890 proved a single plain
-- INSERT works fine, so the SELECT-FROM-VALUES construction itself was
-- the problem, not the data.




SELECT 'f891_gap_fill_count' AS chk, count(*)::int AS n
  FROM public.daily_records WHERE remarks = 'F20_IMPORT_2026-08-24' AND record_date BETWEEN '2025-11-07' AND '2025-12-13';